/* ---------- Statutory rules (excerpts) ---------- */

/* Additional standard deduction for aged or blind individuals */
additional_standard_deduction(Age, Amount) :-
    ( Age >= 65 ->
        Amount = 750
    ; Age < 65 ->
        Amount = 0
    ).

/* ---------- Facts for the case ---------- */

/* Alice's birth date and payment */
alice_birth_date(1950, 3, 2).
alice_payment(33200).

/* ---------- Derivation of Alice's additional standard deduction ---------- */

alice_additional_standard_deduction(Amount) :-
    alice_birth_date(Year, _, _),
    YearOfBirth is 2017 - Year,
    additional_standard_deduction(YearOfBirth, Amount).

/* ---------- Verification of the claim ---------- */

:- (  alice_additional_standard_deduction(Amount),
      Amount =:= 750
   -> format('Result: Entailment~n')
   ;  format('Result: Contradiction~n')
   ).
:- halt.

/* ---------- Statutory rules (excerpts) ---------- */

/* Section 2(b)(1)(A)(ii): Head of household if taxpayer maintains as home a household which is
   for more than half of the taxable year the principal place of abode, as a member of such household,
   of any other person who is a dependent of the taxpayer, if the taxpayer is entitled to a deduction
   for the taxable year for such person under section 151. */

/* For the claim, we need to check if in 2017:
   - Bob (the taxpayer) maintained the home,
   - The home was Charlie's principal place of abode for more than half the year,
   - Charlie was a dependent of Bob in 2017,
   - Bob was entitled to a deduction for Charlie under section 151 for 2017.
   If so, section 2(b)(1)(A)(ii) applies to Charlie as the dependent.
*/

/* ---------- Facts for the case ---------- */

/* Relationships */
married(alice, bob, date(1992,2,3)).
brother(charlie, bob).
dob(charlie, date(2000,10,9)).
died(alice, date(2014,7,9)).

/* Bob maintained the costs of the home for himself and Charlie from 2004 to 2019 */
furnished_cost_of_home(bob, Home, Year) :- between(2004,2019,Year), home(Home), lives_in(bob, Home, Year), lives_in(charlie, Home, Year).
home(main_home).

/* Bob and Charlie lived together in the main home from 2004 to 2019 */
lives_in(bob, main_home, Year) :- between(2004,2019,Year).
lives_in(charlie, main_home, Year) :- between(2004,2019,Year).

/* Bob entitled to a deduction for Charlie under section 151(c) from 2015 to 2019 */
deduction_under_151(bob, charlie, Year) :- between(2015,2019,Year).

/* Bob's income in 2017 */
income(bob, 2017, 5254312).

/* ---------- Statutory predicates for dependents ---------- */

/* Section 151(c) deduction for dependents: if Bob is entitled to a deduction for Charlie under section 151 in 2017,
   then Charlie is Bob's dependent in 2017. */
dependent(bob, charlie, 2017) :- deduction_under_151(bob, charlie, 2017).

/* Principal place of abode for more than one-half of the year */
principal_place_of_abode(charlie, Home, 2017) :-
    lives_in(charlie, Home, 2017).

/* Household is maintained by Bob if Bob furnished over half the cost of maintaining it in 2017 */
maintains_household(bob, Home, 2017) :-
    furnished_cost_of_home(bob, Home, 2017).

/* Section 2(b)(1)(A)(ii) applies to Charlie as the dependent in 2017 if:
      - Bob maintains the household as his home,
      - The household is the principal place of abode (for more than half the year) of Charlie,
      - Charlie is a dependent of Bob in 2017,
      - Bob is entitled to a deduction for Charlie under section 151 in 2017.
*/
section_2b1Aii_applies(bob, charlie, 2017) :-
    home(Home),
    maintains_household(bob, Home, 2017),
    principal_place_of_abode(charlie, Home, 2017),
    dependent(bob, charlie, 2017),
    deduction_under_151(bob, charlie, 2017).

/* ---------- Verification of the claim ---------- */

:- (  section_2b1Aii_applies(bob, charlie, 2017)
   -> format('Result: Entailment~n')
   ;  format('Result: Contradiction~n')
   ).
:- halt.

/* ---------- Statutory rules (excerpts) ---------- */

/* Definition of a qualifying relative bearing a relationship to the taxpayer */
is_qualifying_relative(A, B) :-
    % Check if B is a child or descendant of a child of A
    is_child_or_descendant_of_child(A, B).

/* Function to check if B is a child or descendant of a child of A */
is_child_or_descendant_of_child(_, _) :-
    fail. % Bob is not a child or descendant of a child of Alice

/* ---------- Facts for the case ---------- */

alice_brother(bob).

/* ---------- Derivation of the relationship ---------- */

alice_bears_relationship_to_bob :-
    alice_brother(bob),
    is_qualifying_relative(alice, bob).

/* ---------- Verification of the claim ---------- */

:- (  alice_bears_relationship_to_bob
   -> format('Result: Entailment~n')
   ;  format('Result: Contradiction~n')
   ).
:- halt.

/* s152_d_2_H_pos: Alice bears a relationship to Bob under section 152(d)(2)(H) for 2018.
   Alice and Bob started living together on April 15th, 2014. Alice and Bob are not married.
   Gold: 1 (Entailment) */

/* Section 152(d)(2)(H): An individual (other than an individual who at any time during
   the taxable year was the spouse of the taxpayer) who, for the taxable year of the
   taxpayer, has the same principal place of abode as the taxpayer and is a member of
   the taxpayer's household. */
relationship_152d2h(Individual, Taxpayer, Year) :-
    same_principal_abode(Individual, Taxpayer, Year),
    household_member(Individual, Taxpayer, Year),
    \+ was_spouse_during_year(Individual, Taxpayer, Year).

/* ---------- Facts ---------- */

/* Alice and Bob have lived together since April 15, 2014 - so all of 2018 */
same_principal_abode(alice, bob, 2018).
household_member(alice, bob, 2018).

/* Alice and Bob are not married */
was_spouse_during_year(_, _, _) :- fail.

/* ---------- Verification ---------- */

:- (  relationship_152d2h(alice, bob, 2018)
   -> format('Result: Entailment~n')
   ;  format('Result: Contradiction~n')
   ).
:- halt.

/* ---------- Statutory rules (excerpts) ---------- */

/* Section 151(b): Exemption for spouse if joint return not made, spouse has no gross income, and spouse is not dependent of another taxpayer. */
exemption_for_spouse(Taxpayer, Year) :-
    married(Taxpayer, Spouse, Year),
    not(joint_return_made(Taxpayer, Spouse, Year)),
    spouse_has_no_gross_income(Taxpayer, Spouse, Year),
    spouse_not_dependent_of_another(Taxpayer, Spouse, Year).

/* Married if valid marriage exists in year */
married(alice, bob, 2015).

/* Bob has no gross income in 2015 */
spouse_has_no_gross_income(alice, bob, 2015).

/* No joint return made by Alice and Bob (not specified as made) */
not(joint_return_made(alice, bob, 2015)).

/* Bob is not a dependent of another taxpayer in 2015 */
spouse_not_dependent_of_another(alice, bob, 2015).

/* ---------- Facts for the case ---------- */

/* All facts above already encoded. */

/* ---------- Verification of the claim ---------- */

alice_can_receive_exemption_for_bob_2015 :-
    exemption_for_spouse(alice, 2015).

:- (  alice_can_receive_exemption_for_bob_2015
   -> format('Result: Entailment~n')
   ;  format('Result: Contradiction~n')
   ).
:- halt.
